class Solution {
public:
    vector<int> smallestSufficientTeam(vector<string>& req_skills, vector<vector<string>>& people) {
        int n = req_skills.size();
        unordered_map<string, int> skill_map;
        for (int i = 0; i < n; ++i) skill_map[req_skills[i]] = i;

        int total_masks = 1 << n;
        vector<vector<int>> dp(total_masks);
        vector<bool> reached(total_masks, false);
        reached[0] = true;

        for (int i = 0; i < (int)people.size(); ++i) {
            int p_mask = 0;
            for (const string& s : people[i]) {
                if (skill_map.count(s)) p_mask |= (1 << skill_map[s]);
            }
            if (p_mask == 0) continue;

            for (int mask = 0; mask < total_masks; ++mask) {
                if (!reached[mask]) continue;
                int combined = mask | p_mask;
                if (!reached[combined] || dp[mask].size() + 1 < dp[combined].size()) {
                    reached[combined] = true;
                    dp[combined] = dp[mask];
                    dp[combined].push_back(i);
                }
            }
        }
        return dp[total_masks - 1];
    }
};

import java.util.*;

class Solution {
    public int[] smallestSufficientTeam(String[] req_skills, List<List<String>> people) {
        int n = req_skills.length;
        Map<String, Integer> skillMap = new HashMap<>();
        for (int i = 0; i < n; i++) skillMap.put(req_skills[i], i);

        int totalMasks = 1 << n;
        List<Integer>[] dp = new List[totalMasks];
        dp[0] = new ArrayList<>();

        for (int i = 0; i < people.size(); i++) {
            int pMask = 0;
            for (String s : people.get(i)) {
                if (skillMap.containsKey(s)) {
                    pMask |= (1 << skillMap.get(s));
                }
            }
            if (pMask == 0) continue;

            for (int mask = 0; mask < totalMasks; mask++) {
                if (dp[mask] == null) continue;
                int combined = mask | pMask;
                if (dp[combined] == null || dp[mask].size() + 1 < dp[combined].size()) {
                    dp[combined] = new ArrayList<>(dp[mask]);
                    dp[combined].add(i);
                }
            }
        }

        List<Integer> best = dp[totalMasks - 1];
        int[] res = new int[best.size()];
        for (int i = 0; i < best.size(); i++) res[i] = best.get(i);
        return res;
    }
}

var smallestSufficientTeam = function(req_skills, people) {
    const n = req_skills.length;
    const skillMap = new Map();
    for (let i = 0; i < n; i++) skillMap.set(req_skills[i], i);

    const dp = new Map();
    dp.set(0, []);

    for (let i = 0; i < people.length; i++) {
        let pMask = 0;
        for (const s of people[i]) {
            if (skillMap.has(s)) {
                pMask |= (1 << skillMap.get(s));
            }
        }
        if (pMask === 0) continue;

        const newEntries = [];
        for (const [mask, team] of dp.entries()) {
            const combined = mask | pMask;
            if (!dp.has(combined) || team.length + 1 < dp.get(combined).length) {
                newEntries.push([combined, team.concat(i)]);
            }
        }
        for (const [m, t] of newEntries) {
            if (!dp.has(m) || t.length < dp.get(m).length) {
                dp.set(m, t);
            }
        }
    }
    return dp.get((1 << n) - 1);
};
